# November 24, 2026: a fourth scatter of places across Manitoba (13 added), the thinnest state or province on the map,
# claimed with tools/choose.py --claim --thinnest. Sources opened in this session: the Province's Provincial Heritage Site
# pages (gov.mb.ca/chc/hrb/prov, with the list of all designated sites), the Manitoba Historical Society's "Historic Sites of
# Manitoba" page for each place (mhs.mb.ca, read with tools/page.py; each gives a site coordinate), the Wikipedia articles
# for Union Station and the Fort Garry Hotel, the Commonwealth Air Training Plan Museum's own season notice, the Gilbert
# Plains Historical Society's page for the Negrych homestead, and VIA Rail's Winnipeg station page.
from data_b import N
from data_ma import W
def L(t,u): return [t,u]
def MHS(t,s): return ['Manitoba Historical Society: '+t,'https://mhs.mb.ca/docs/sites/'+s+'.shtml']
def PHS(n): return ['Province of Manitoba: Provincial Heritage Site No. '+str(int(n)),'https://www.gov.mb.ca/chc/hrb/prov/p'+n+'.html']

